class Auto(object):
    """Evaluate a subspec using glom's automatic container interpretation."""
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope.new_child({_MODE: 'auto'}))

    def __repr__(self):
        return 'Auto(%r)' % (self.spec,)


class Fill(Auto):
    """Build containers recursively, treating plain values as literals.

    Explicit specifiers (including T and Auto) still evaluate normally.
    """
    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope.new_child({_MODE: 'fill'}))

    def __repr__(self):
        return 'Fill(%r)' % (self.spec,)


class Let(object):
    """Bind named subspec results in the current scope without changing target."""
    def __init__(self, **bindings):
        self.bindings = bindings

    def glomit(self, target, scope):
        values = {name: scope[glom](target, spec, scope)
                  for name, spec in self.bindings.items()}
        # _glom gives each evaluation a child scope; bindings belong to the
        # containing pipeline so subsequent specs can refer to them with S.
        scope.maps[1].update(values)
        return target

    def __repr__(self):
        return 'Let(%s)' % ', '.join('%s=%r' % item for item in self.bindings.items())


_MODE = make_sentinel('_MODE')


def _fill(target, spec, scope):
    recur = lambda value: scope[glom](target, value, scope)
    if isinstance(spec, dict):
        return type(spec)((recur(k), recur(v)) for k, v in spec.items())
    if isinstance(spec, (list, tuple, set, frozenset)):
        return type(spec)(recur(v) for v in spec)
    if callable(spec):
        return spec(target)
    return spec
