"""Lazy iterable transformations for glom specifications."""
import itertools

from boltons.iterutils import chunked_iter, windowed_iter, unique_iter
from .core import T, SKIP, STOP, glom, TargetRegistry, Path


class Iter(object):
    """Apply a subspec to each target element, lazily.

    Transformations return new specs, leaving the original reusable. Use
    ``all()`` to collect a list or ``first()`` to select the first result.
    """
    def __init__(self, subspec=T, sentinel=STOP):
        self.subspec = subspec
        self.sentinel = sentinel
        self._steps = ()

    def _chain(self, name, *args):
        ret = type(self)(self.subspec, self.sentinel)
        ret._steps = self._steps + ((name, args),)
        return ret

    def map(self, subspec):
        return self._chain('map', subspec)

    def filter(self, key=T):
        return self._chain('filter', key)

    def chunked(self, size, **kwargs):
        return self._chain('chunked', size, kwargs)

    def windowed(self, size):
        return self._chain('windowed', size)

    def flatten(self):
        return self._chain('flatten')

    def unique(self, key=T):
        return self._chain('unique', key)

    def dropwhile(self, key=T):
        return self._chain('dropwhile', key)

    def takewhile(self, key=T):
        return self._chain('takewhile', key)

    def slice(self, *args):
        return self._chain('slice', *args)

    def limit(self, count):
        return self.slice(count)

    def enumerate(self, start=0):
        return self._chain('enumerate', start)

    def all(self):
        return (self, list)

    def first(self, key=T, default=None):
        return (self, First(key=key, default=default))

    def glomit(self, target, scope):
        evaluate = lambda item, spec: scope[glom](item, spec, scope)
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])

        def mapped(source, spec):
            for item in source:
                value = evaluate(item, spec)
                if value is self.sentinel:
                    break
                if value is not SKIP:
                    yield value

        result = mapped(iterate(target), self.subspec)
        for name, args in self._steps:
            if name == 'map':
                result = mapped(result, args[0])
            elif name in ('filter', 'dropwhile', 'takewhile', 'unique'):
                # Bind this step's spec now, not when the iterator is consumed.
                key = lambda item, spec=args[0]: evaluate(item, spec)
                if name == 'filter':
                    result = filter(key, result)
                elif name == 'unique':
                    result = unique_iter(result, key=key)
                else:
                    result = getattr(itertools, name)(key, result)
            elif name == 'chunked':
                result = chunked_iter(result, args[0], **args[1])
            elif name == 'windowed':
                result = windowed_iter(result, args[0])
            elif name == 'flatten':
                result = itertools.chain.from_iterable(result)
            elif name == 'slice':
                result = itertools.islice(result, *args)
            elif name == 'enumerate':
                result = enumerate(result, args[0])
        return result

    def __repr__(self):
        text = 'Iter(%r)' % (self.subspec,)
        for name, args in self._steps:
            text += '.%s(%s)' % (name, ', '.join(map(repr, args)))
        return text


class First(object):
    """Return the first element whose key spec is truthy, or default."""
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        for item in iterate(target):
            if scope[glom](item, self.key, scope):
                return item
        return self.default

    def __repr__(self):
        return 'First(key=%r, default=%r)' % (self.key, self.default)
